-- Theory questions for MTH 242. Safe to run twice.
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Mean value theorem$q$, $q$State the mean value theorem and verify it for f(x) = x^3 on [0, 2].$q$, 5, $q$The mean value theorem: if f is continuous on [a, b] and differentiable on (a, b), then there is a point c in (a, b) with f'(c) = (f(b) - f(a))/(b - a). For f(x) = x^3 on [0, 2], f(2) = 8 and f(0) = 0, so the chord slope is 8/2 = 4. Now f'(x) = 3x^2, so 3c^2 = 4 and c = 2/sqrt(3), which is about 1.155. This number lies in (0, 2), so the theorem is verified.$q$, $q$[{"t":"Statement of the theorem","m":2},{"t":"Chord slope 4","m":1},{"t":"3c^2 = 4","m":1},{"t":"c = 2/sqrt(3) and checks it is in (0, 2)","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the mean value theorem and verify it for f(x) = x^3 on [0, 2].$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Taylor series$q$, $q$Write the Taylor series of f about x = a. Find the Maclaurin series of ln(1 + x) up to the term in x^4.$q$, 5, $q$The Taylor series of f about a is f(a) + f'(a)(x - a) + f''(a)(x - a)^2/2! + f'''(a)(x - a)^3/3! + ... For f(x) = ln(1 + x) about 0: f(0) = 0, f'(x) = 1/(1 + x) so f'(0) = 1, f''(x) = -1/(1 + x)^2 so f''(0) = -1, f'''(x) = 2/(1 + x)^3 so f'''(0) = 2 and the fourth derivative at 0 is -6. So ln(1 + x) = x - x^2/2 + x^3/3 - x^4/4 + ...$q$, $q$[{"t":"General Taylor formula","m":2},{"t":"Derivatives at 0 are 1, -1, 2, -6","m":1},{"t":"Coefficients 1, -1/2, 1/3, -1/4","m":1},{"t":"Final series","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Write the Taylor series of f about x = a. Find the Maclaurin series of ln(1 + x) up to the term in x^4.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Partial derivatives$q$, $q$Find the first partial derivatives and the mixed second derivative of f(x, y) = x^2 y + y^3.$q$, 5, $q$To differentiate with respect to x treat y as a constant: f_x = 2xy. To differentiate with respect to y treat x as a constant: f_y = x^2 + 3y^2. The mixed derivative f_xy is found by differentiating f_x with respect to y: f_xy = 2x. Check by differentiating f_y with respect to x: f_yx = 2x, which is the same.$q$, $q$[{"t":"f_x = 2xy","m":1},{"t":"f_y = x^2 + 3y^2","m":1},{"t":"f_xy = 2x","m":2},{"t":"Checks with f_yx","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Find the first partial derivatives and the mixed second derivative of f(x, y) = x^2 y + y^3.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Chain rule$q$, $q$State the chain rule for z = f(x, y) where x and y depend on t. For z = x^2 + y^2 with x = cos t and y = sin t, find dz/dt.$q$, 5, $q$The chain rule is dz/dt = (partial z/partial x)(dx/dt) + (partial z/partial y)(dy/dt). Here partial z/partial x = 2x, partial z/partial y = 2y, dx/dt = -sin t and dy/dt = cos t. So dz/dt = 2 cos t(-sin t) + 2 sin t cos t = 0. This agrees with the fact that z = cos^2 t + sin^2 t = 1 is constant.$q$, $q$[{"t":"Chain rule formula","m":2},{"t":"The four derivatives","m":1},{"t":"dz/dt = 0","m":1},{"t":"Checks that z = 1 is constant","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the chain rule for z = f(x, y) where x and y depend on t. For z = x^2 + y^2 with x = cos t and y = sin t, find dz/dt.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Extrema$q$, $q$Find and classify the stationary point of f(x, y) = x^2 + y^2 - 2x - 4y + 5.$q$, 5, $q$Set the first partial derivatives to zero: f_x = 2x - 2 = 0 gives x = 1, and f_y = 2y - 4 = 0 gives y = 2. The stationary point is (1, 2). The second derivatives are f_xx = 2, f_yy = 2 and f_xy = 0. D = f_xx f_yy - (f_xy)^2 = 4, which is positive, and f_xx is positive, so the point is a local minimum. The minimum value is f(1, 2) = 1 + 4 - 2 - 8 + 5 = 0.$q$, $q$[{"t":"Sets f_x = 0 and f_y = 0","m":1},{"t":"Stationary point (1, 2)","m":1},{"t":"Second derivative test D = 4","m":1},{"t":"Concludes a minimum","m":1},{"t":"Minimum value 0","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Find and classify the stationary point of f(x, y) = x^2 + y^2 - 2x - 4y + 5.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Lagrange multipliers$q$, $q$Use the method of Lagrange multipliers to find the maximum value of xy subject to x + y = 10.$q$, 5, $q$Let f = xy and the constraint g = x + y - 10 = 0. Set grad f = lambda grad g. This gives y = lambda and x = lambda, together with x + y = 10. So x = y. Then 2x = 10, giving x = y = 5. The maximum value of xy is 25. This agrees with the fact that for a fixed sum the product is largest when the two numbers are equal.$q$, $q$[{"t":"Forms f, the constraint and the Lagrange condition","m":1},{"t":"y = lambda and x = lambda","m":1},{"t":"x = y = 5","m":1},{"t":"Maximum 25","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Use the method of Lagrange multipliers to find the maximum value of xy subject to x + y = 10.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Linear approximation$q$, $q$Write the linear approximation of f(x, y) near a point (a, b). Use it to estimate the square root of (3.03^2 + 3.96^2).$q$, 5, $q$The linear approximation is f(x, y) is about f(a, b) + f_x(a, b)(x - a) + f_y(a, b)(y - b). Take f(x, y) = sqrt(x^2 + y^2) at (3, 4). Then f(3, 4) = 5, f_x = x/sqrt(x^2 + y^2) = 3/5 and f_y = y/sqrt(x^2 + y^2) = 4/5. With x - a = 0.03 and y - b = -0.04, the estimate is 5 + 0.6(0.03) + 0.8(-0.04) = 5 + 0.018 - 0.032 = 4.986.$q$, $q$[{"t":"Linear approximation formula","m":1},{"t":"f(3, 4) = 5","m":1},{"t":"f_x = 3/5 and f_y = 4/5","m":1},{"t":"Substitutes the increments","m":1},{"t":"Estimate 4.986","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Write the linear approximation of f(x, y) near a point (a, b). Use it to estimate the square root of (3.03^2 + 3.96^2).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Line integrals$q$, $q$Evaluate the line integral of (x dx + y dy) along the straight line from (0, 0) to (1, 1).$q$, 5, $q$Along the line y = x we have dy = dx, with x going from 0 to 1. The integral becomes the integral from 0 to 1 of (x + x) dx = the integral of 2x dx = [x^2] from 0 to 1 = 1. Check: x dx + y dy is the differential of (x^2 + y^2)/2, so the integral equals the change in that potential, (1 + 1)/2 - 0 = 1.$q$, $q$[{"t":"Parametrises y = x with dy = dx","m":1},{"t":"Reduces to the integral of 2x dx","m":1},{"t":"Answer 1","m":2},{"t":"Optional check using the potential function","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Evaluate the line integral of (x dx + y dy) along the straight line from (0, 0) to (1, 1).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Multiple integrals$q$, $q$Evaluate the double integral of (x + y) over the rectangle 0 less than or equal to x less than or equal to 1 and 0 less than or equal to y less than or equal to 2.$q$, 5, $q$Integrate with respect to y first: the integral from 0 to 2 of (x + y) dy = [xy + y^2/2] from 0 to 2 = 2x + 2. Now integrate with respect to x: the integral from 0 to 1 of (2x + 2) dx = [x^2 + 2x] from 0 to 1 = 1 + 2 = 3.$q$, $q$[{"t":"Sets up the iterated integral","m":1},{"t":"Inner integral 2x + 2","m":2},{"t":"Outer integral gives 3","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Evaluate the double integral of (x + y) over the rectangle 0 less than or equal to x less than or equal to 1 and 0 less than or equal to y less than or equal to 2.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$MTH 242$q$, $q$Mathematical Methods I$q$, $q$Multiple integrals$q$, $q$Evaluate the triple integral of xyz over the cube 0 less than or equal to x, y, z less than or equal to 1.$q$, 5, $q$Because the integrand is a product of functions of single variables and the region is a cube, the triple integral equals the product of three single integrals. Each integral from 0 to 1 of x dx = 1/2. So the triple integral is (1/2)(1/2)(1/2) = 1/8.$q$, $q$[{"t":"Separates into three single integrals","m":2},{"t":"Each equals 1/2","m":2},{"t":"Answer 1/8","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Evaluate the triple integral of xyz over the cube 0 less than or equal to x, y, z less than or equal to 1.$q$);
select course_code, count(*) as questions from public.theory_questions group by course_code order by course_code;
